from typing import Annotated, Any, Literal
from pydantic import BaseModel
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

# We need to import Tag and Discriminator. 
# Wait, Tag and Discriminator are from pydantic, not fastapi.
# Let me check if they are available in the environment.
# Actually, they are from pydantic.v2.
from pydantic import Discriminator, Tag

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()
@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert():
    # This should be a body parameter. If it's treated as a query parameter, 
    # it will fail to validate the body or expect it in query.
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 10, "num_ingredients": 3})
    print(f"Response: {response.status_code}, {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_dessert()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
